        actual_set text; bad_hash boolean; category text; kind text; expected_registry text;
        actual_category_count integer; actual_category_digest text; expected jsonb; expected_catalog jsonb;
begin
  if p_registry_version not in ('scac-mutation-registry.v1','scac-mutation-registry.v2','scac-mutation-registry.v3','scac-mutation-registry.v4','scac-mutation-registry.v5','scac-mutation-registry.v6','scac-mutation-registry.v7','scac-mutation-registry.v8','scac-mutation-registry.v9','scac-mutation-registry.v10','scac-mutation-registry.v11','scac-mutation-registry.v12','scac-mutation-registry.v13','scac-mutation-registry.v14','scac-mutation-registry.v15','scac-mutation-registry.v16','scac-mutation-registry.v17','scac-mutation-registry.v18','scac-mutation-registry.v19','scac-mutation-registry.v20','scac-mutation-registry.v21','scac-mutation-registry.v22','scac-mutation-registry.v23','scac-mutation-registry.v24','scac-mutation-registry.v25','scac-mutation-registry.v26','scac-mutation-registry.v27','scac-mutation-registry.v28','scac-mutation-registry.v29','scac-mutation-registry.v30','scac-mutation-registry.v31','scac-mutation-registry.v32','scac-mutation-registry.v33','scac-mutation-registry.v34','scac-mutation-registry.v35','scac-mutation-registry.v36','scac-mutation-registry.v37','scac-mutation-registry.v38','scac-mutation-registry.v39','scac-mutation-registry.v40','scac-mutation-registry.v41','scac-mutation-registry.v42','scac-mutation-registry.v43','scac-mutation-registry.v44','scac-mutation-registry.v45','scac-mutation-registry.v46','scac-mutation-registry.v47','scac-mutation-registry.v48','scac-mutation-registry.v49','scac-mutation-registry.v50','scac-mutation-registry.v51','scac-mutation-registry.v52','scac-mutation-registry.v53','scac-mutation-registry.v54','scac-mutation-registry.v55','scac-mutation-registry.v56','scac-mutation-registry.v57','scac-mutation-registry.v58','scac-mutation-registry.v59','scac-mutation-registry.v60','scac-mutation-registry.v61','scac-mutation-registry.v62','scac-mutation-registry.v63','scac-mutation-registry.v64','scac-mutation-registry.v65','scac-mutation-registry.v66','scac-mutation-registry.v67','scac-mutation-registry.v68','scac-mutation-registry.v69','scac-mutation-registry.v70','scac-mutation-registry.v71','scac-mutation-registry.v72','scac-mutation-registry.v73','scac-mutation-registry.v74','scac-mutation-registry.v75','scac-mutation-registry.v76','scac-mutation-registry.v77','scac-mutation-registry.v78','scac-mutation-registry.v79','scac-mutation-registry.v80','scac-mutation-registry.v81','scac-mutation-registry.v82','scac-mutation-registry.v83','scac-mutation-registry.v84','scac-mutation-registry.v85','scac-mutation-registry.v86','scac-mutation-registry.v87','scac-mutation-registry.v88','scac-mutation-registry.v89','scac-mutation-registry.v90','scac-mutation-registry.v91','scac-mutation-registry.v92','scac-mutation-registry.v93','scac-mutation-registry.v94','scac-mutation-registry.v95','scac-mutation-registry.v96','scac-mutation-registry.v97','scac-mutation-registry.v98','scac-mutation-registry.v99','scac-mutation-registry.v100','scac-mutation-registry.v101','scac-mutation-registry.v102','scac-mutation-registry.v103','scac-mutation-registry.v104','scac-mutation-registry.v105','scac-mutation-registry.v106','scac-mutation-registry.v107','scac-mutation-registry.v108','scac-mutation-registry.v109','scac-mutation-registry.v110','scac-mutation-registry.v111','scac-mutation-registry.v112','scac-mutation-registry.v113','scac-mutation-registry.v114','scac-mutation-registry.v115') then return false; end if;
  expected_registry:=case p_registry_version
